<?php
session_start();
require_once __DIR__ . '/../includes/role_helpers.php';
requireAnyRole(['supplier']);
require_once __DIR__ . '/../config/database.php';
require_once __DIR__ . '/../includes/supplier_account.php';
$userId=(int)$_SESSION['user_id'];$profile=ensureSupplierProfile($conn,$userId,$_SESSION['name']??'Supplier');$message='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    $supplierName=trim($_POST['supplier_name']??'');$contact=trim($_POST['contact_person']??'');$phone=trim($_POST['phone']??'');$email=trim($_POST['email']??'');$address=trim($_POST['address']??'');
    if($supplierName===''){$message='Supplier name is required.';}elseif($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL)){$message='Please enter a valid email address.';}else{
        $stmt=$conn->prepare("UPDATE suppliers SET supplier_name=?,contact_person=?,phone=?,email=?,address=? WHERE id=? AND user_id=?");$sid=(int)$profile['id'];$stmt->bind_param('sssssii',$supplierName,$contact,$phone,$email,$address,$sid,$userId);$stmt->execute();$stmt->close();$success='Supplier profile updated.';$profile=ensureSupplierProfile($conn,$userId,$_SESSION['name']??'Supplier');
    }
}
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Supplier Profile</title><style>*{box-sizing:border-box;font-family:Arial,sans-serif}body{margin:0;min-height:100vh;color:#fff;background:#121426}.wrap{max-width:760px;margin:auto;padding:34px 22px}.panel{background:#262740;border:1px solid #3c3e62;border-radius:16px;padding:28px}.muted{color:#b8bdd6}.group{margin:16px 0}.group label{display:block;font-weight:800;font-size:12px;margin-bottom:7px}.group input,.group textarea{width:100%;padding:12px;border-radius:9px;border:1px solid #4a4c71;background:#202036;color:#fff;outline:none}.group textarea{min-height:100px;resize:vertical}.btn{border:0;border-radius:9px;padding:12px 18px;background:linear-gradient(135deg,#c06ceb,#5df09d);color:#17182c;font-weight:900;cursor:pointer}.alert{padding:12px 14px;border-radius:9px;margin:14px 0}.error{background:rgba(192,108,235,.12);border:1px solid rgba(192,108,235,.4)}.success{background:rgba(93,240,157,.12);border:1px solid rgba(93,240,157,.4)}</style></head><body><?php include __DIR__.'/nav.php'; ?><main class="wrap"><section class="panel"><h1 style="margin-top:0">Manage Supplier Profile</h1><p class="muted">Update the contact information used for your Supplier account.</p><?php if($message): ?><div class="alert error"><?php echo htmlspecialchars($message); ?></div><?php endif; ?><?php if($success): ?><div class="alert success"><?php echo htmlspecialchars($success); ?></div><?php endif; ?><form method="post"><div class="group"><label>Supplier / Business Name</label><input name="supplier_name" value="<?php echo htmlspecialchars($profile['supplier_name']); ?>" required></div><div class="group"><label>Contact Person</label><input name="contact_person" value="<?php echo htmlspecialchars($profile['contact_person']); ?>"></div><div class="group"><label>Phone</label><input name="phone" value="<?php echo htmlspecialchars($profile['phone']); ?>"></div><div class="group"><label>Email</label><input type="email" name="email" value="<?php echo htmlspecialchars($profile['email']); ?>"></div><div class="group"><label>Address</label><textarea name="address"><?php echo htmlspecialchars($profile['address']); ?></textarea></div><button class="btn" type="submit">Save Profile</button></form></section></main></body></html>
